url='https://sourcegraph.com/.api/search/stream?q='+urllib.parse.quote(q)+'&v=V3'
req=urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0','Accept':'text/event-stream'})
try:
 data=urllib.request.urlopen(req,timeout=60).read().decode('utf-8','ignore')
 for line in data.splitlines():
  if line.startswith('event: matches') or line.startswith('data: [{\"type\":\"content\"'):
   print(line[:3000])
except Exception as e: print('ERR',e)
